const toolCall = $json.body?.message?.toolCallList?.[0] || {};
const args = toolCall.function?.arguments || {};

const now = new Date();
const startWindow = new Date(now.getTime() + 60 * 60 * 1000);
const endWindow = new Date(now.getTime() + 5 * 24 * 60 * 60 * 1000);

return {
  toolCallId: toolCall.id || '',
  start: startWindow.toISOString(),
  end: endWindow.toISOString(),
  urgency: args.urgency || 'Routine'
};

const toolCallId = $('Code: Parse Availability Request').item.json.toolCallId;
// $json here is Cal.com's response, not the original webhook body - the
// call id has to be pulled from the webhook trigger node explicitly, not
// assumed to still be on $json this far downstream.
const webhookBody = $('Webhook: Check Availability').item.json.body || {};
const callId = webhookBody.message?.call?.id || webhookBody.call?.id || '';
let resultText;

try {
  const slots = $json.data || $json.slots || [];
  const flat = Array.isArray(slots) ? slots : Object.values(slots).flat();
  const top = flat.slice(0, 3);

  if (!top.length) {
    resultText = 'No slots came back from the calendar in the next few days. Tell the caller a team member will call them back within the hour to schedule.';
  } else {
    // The model is unreliable at reproducing an exact ISO date string, so it
    // never has to - it only ever picks an option number, and n8n resolves
    // the real timestamp from what was actually offered. Stashed in workflow
    // static data, keyed by call id, since check_availability and
    // book_appointment are separate webhook calls with no shared memory.
    const isoTimes = top.map(s => new Date(s.start || s.time || s).toISOString());
    const staticData = $getWorkflowStaticData('global');
    staticData.offeredSlots = staticData.offeredSlots || {};
    staticData.offeredSlots[callId] = isoTimes;

    const lines = isoTimes.map((iso, i) => {
      const readable = new Date(iso).toLocaleString('en-US', { weekday: 'long', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
      return `${i + 1}. ${readable}`;
    });
    resultText = 'Available times:\n' + lines.join('\n') + '\n\nRead the caller these options in plain language. Once they pick one, call book_appointment with selectedOption set to that option\'s number (1, 2, or 3) - never state or reconstruct a date/time yourself, just pass the number.';
  }
} catch (e) {
  resultText = 'Could not reach the calendar system. Tell the caller a team member will call them back within the hour to schedule.';
}

return { toolCallId, resultText };

const toolCall = $json.body?.message?.toolCallList?.[0] || {};
const args = toolCall.function?.arguments || {};
const callId = $json.body?.message?.call?.id || $json.body?.call?.id || '';

// Resolve the real ISO time from what check_availability actually offered,
// keyed by call id - the model only ever passes an option number, never a
// date it has to reproduce itself.
const staticData = $getWorkflowStaticData('global');
const offered = (staticData.offeredSlots && staticData.offeredSlots[callId]) || [];
const optionIndex = parseInt(args.selectedOption, 10);
let selectedStartTime = (optionIndex >= 1 && optionIndex <= offered.length) ? offered[optionIndex - 1] : '';

// Defense in depth: even a resolved slot must still be a valid future time.
const parsed = selectedStartTime ? new Date(selectedStartTime) : null;
if (!parsed || isNaN(parsed.getTime()) || parsed.getTime() <= Date.now()) {
  selectedStartTime = '';
}

// Clean up now that it's been consumed, so static data doesn't grow
// unbounded across calls.
if (staticData.offeredSlots) delete staticData.offeredSlots[callId];

return {
  toolCallId: toolCall.id || '',
  callerName: args.callerName || '',
  callerPhone: args.callerPhone || '',
  propertyAddress: args.propertyAddress || '',
  issueDescription: args.issueDescription || '',
  category: args.category || 'General',
  urgency: args.urgency || 'Routine',
  selectedStartTime
};

